# A glyph’s citation reading must not inherit a particle/verb override.
for number, readings in {18:{'干':'gān','地':'dì'},19:{'得':'dé','要':'yào'},20:{'干':'gàn'}}.items():
    path=ROOT/'content/packs'/f's1-u{number:02}.json'
    pack=read(path)
    for c in pack['characters']:
        if c['hanzi'] in readings:c['pinyin']=readings[c['hanzi']]
    path.write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n','utf-8')

